mapper.update:
UPDATE t_help_doc
SET
    page_view_count = page_view_count + #{pageViewCountIncrease},
    user_view_count = user_view_count + #{userViewCountIncrease}
WHERE help_doc_id = #{helpDocId}

mapper.select:
SELECT COUNT(*)
FROM t_help_doc_view_record
WHERE help_doc_id = #{helpDocId} AND user_id = #{userId}

SELECT user_id, user_name, page_view_count, first_ip, first_user_agent, create_time, last_ip, last_user_agent, update_time FROM t_help_doc_view_record
AND help_doc_id = #{query.helpDocId}
AND user_id = #{query.userId}
AND INSTR(user_name, #{query.keywords})
ORDER BY create_time DESC
